func (s Store) latestNegativeReview(ref string) (*ReviewBundle, *ReviewAttestation) {
	bundles, err := s.ListReviewBundles(ref)
	if err != nil {
		return nil, nil
	}
	replaced := replacedReviewBundles(bundles)
	bundles = reviewBundleLineage(bundles)
	for i := range bundles {
		attestations, attErr := s.ListReviewAttestations(bundles[i].BundleID)
		if attErr != nil || len(attestations) == 0 {
			continue
		}
		att := attestations[len(attestations)-1]
		if att.Decision != "rejected" && att.Decision != "changes-requested" {
			if replaced[bundles[i].BundleID] {
				continue
			}
			return nil, nil
		}
		bundle := bundles[i]
		return &bundle, &att
	}
	return nil, nil
}

func (s Store) scopeLifecycleDone(scope ScopeRef) (bool, error) {
	switch scope.Kind {
	case "spec":
		sp, err := s.GetSpec(scope.Slug)
		if err != nil {
			return false, err
		}
		return sp.Status == "done", nil
	case "milestone":
		rm, err := s.GetRoadmap(scope.Roadmap)
		if err != nil {
			return false, err
		}
		for _, milestone := range rm.Milestones {
			if milestone.ID == scope.Milestone {
				for _, raw := range milestone.Specs {
					slug, external := s.milestoneMember(raw)
					if external {
						if !s.externalMemberDone(raw) {
							return false, nil
						}
						continue
					}
					sp, specErr := s.GetSpec(slug)
					if specErr != nil {
						return false, specErr
					}
					if sp.Status != "done" {
						return false, nil
					}
				}
				return true, nil
			}
		}
		return false, fmt.Errorf("pose: milestone %s/%s not found", scope.Roadmap, scope.Milestone)
	case "roadmap":
		rm, err := s.GetRoadmap(scope.Slug)
		if err != nil {
			return false, err
		}
		return rm.Status == "done", nil
	default:
		return false, nil
	}
}

func (s Store) reviewRequiredForScope(scope ScopeRef, policy ReviewPolicy) (bool, error) {
	if !policy.Enabled {
		return false, nil
	}
	if policy.RequireReviewForLegacyDoneScopes || policy.AdoptedAt == "" {
		return true, nil
	}
	adoptedAt, err := time.Parse(time.DateOnly, policy.AdoptedAt)
	if err != nil {
		return true, nil
	}

	var createdAt, status string
	switch scope.Kind {
	case "spec":
		sp, err := s.GetSpec(scope.Slug)
		if err != nil {
			return false, err
		}
		createdAt, status = sp.CreatedAt, sp.Status
	case "milestone":
		rm, err := s.GetRoadmap(scope.Roadmap)
		if err != nil {
			return false, err
		}
		createdAt, status = rm.CreatedAt, rm.Status
	case "roadmap":
		rm, err := s.GetRoadmap(scope.Slug)
		if err != nil {
			return false, err
		}
		createdAt, status = rm.CreatedAt, rm.Status
	}
	if status != "done" {
		return true, nil
	}
	created, err := time.Parse(time.DateOnly, createdAt)
	if err != nil {
		return true, nil
	}
	return !created.Before(adoptedAt), nil

