// milestoneReachedObligations projects the milestones that can be closed. The
// rule restricts nothing: a reached milestone waits for an operator to close it,
// and the roadmap's own close refuses it anyway. What cannot be read leaves the
// producer's coverage incomplete and never reads as reached.
func (s Store) milestoneReachedObligations(project, scope string, coverage *Coverage) ([]Obligation, error) {
	lost := func(err error) ([]Obligation, error) {
		markCoverageIncomplete(coverage, "reached milestones could not be read: "+err.Error())
		return nil, nil
	}
	spec, within := "", scope
	if ref, err := ParseScopeRef(scope); scope != "" && err == nil && ref.Kind == "spec" {
		spec, within = ref.Slug, ""
	}
	candidates, err := s.milestonesWithTerminalMembers(spec, within)
	if err != nil {
		return lost(err)
	}
	recorded, refused, err := s.milestonesWithRecordedApproval(append(candidates, s.soleMemberRefs(candidates)...))
	if err != nil {
		return lost(err)
	}
	policy, _, err := s.loadReviewPolicy()
	if err != nil {
		return lost(err)
	}
	var out []Obligation
	for _, ref := range candidates {
		parsed, err := ParseScopeRef(ref)
		if err != nil {
			return nil, err
		}
		required, err := s.reviewRequiredForScope(parsed, policy)
		if err != nil {
			return lost(err)
		}
		if policy.CloseoutReviewAdopted() {
			// Under an adopted closeout review policy a reached milestone is
			// closed only by its explicit close, which publishes a receipt,
			// approved review or not (spec pose-closeout-review-policy-by-cost-benefit).
			closed, err := s.closedByReceipt(ref)
			if err != nil {
				return lost(err)
			}
			if closed {
				continue
			}
		} else {
			member, sole := s.soleMemberOf(parsed)
			owed := !recorded[ref] && !(sole && recorded["spec:"+member]) && s.declaredUnreviewed(parsed) == ""
			if !required || !owed && !refused[ref] {
				continue
			}
		}
		source := QualifyNodeRef(project, ArtifactRef{Kind: "milestone", Slug: parsed.Roadmap, Milestone: parsed.Milestone}, "", "")
		o := newObligation(project, "closeout", source, "milestone-reached", ref)
		o.Category = ObligationReconciliation
		o.ReasonCode = "milestone-reached"
		o.Condition = DiagnosticCatalog["milestone-reached"].Condition
		o.Effects = []ObligationEffect{{Phase: PhaseCloseout, Mode: EffectAdvisory}}
		o.Waiting = WaitingActor
		o.Message = ref + " is reached: pose close " + ref
		out = append(out, o)

