	receipt, _, err := posepkg.Store{Root: root}.ReplaceIndexOrLegacy("delivery-integrity.json", data)
	switch {
	case err == nil:
		if receipt.CleanupError != nil {
			render(io.Discard, stderr).Failure("pose: retention of old index generations failed: " + receipt.CleanupError.Error())
		}
	case receipt.Committed:
		render(io.Discard, stderr).Failure("pose: the delivery index was published as generation " + receipt.GenerationID + ", but its durability could not be confirmed: " + err.Error() + "; run `pose index --verify`")
	default:
		render(io.Discard, stderr).Failure("pose: the delivery index was not refreshed: " + err.Error() + "; run `pose index`")
	}
}

// `roadmap-check` reaches its gate
// (spec pose-roadmap-check-reaches-its-gate).
//
// The graph builder returned before it loaded a single roadmap when the
// delivery profile index was absent, so the command reported zero cut criteria
// and exited 0 on a repository whose roadmap declared several. A gate that
// cannot evaluate its criteria was reading as a gate that passed them.
//
// It was found while writing a coverage fixture: the first version of that
// fixture had no profile index, and both --strict and --tolerant returned 0 on
// a criterion naming a delivery target that does not exist.

package cli

